import re

def tokenize_words(text):
    return re.findall(r"\w+|[^\w\s]", text, flags=re.UNICODE)

text = "Hello, NLP! It's useful in 2026."
print(tokenize_words(text))

import re

def tokenize(text):
    text = " ".join(text.split())
    return re.findall(r"\w+|[^\w\s]", text, flags=re.UNICODE)

examples = ["Hello, world!", "NLP is useful.", "AI models learn."]
for sentence in examples:
    print(sentence, "->", tokenize(sentence))
